    ('b1f4852f-b642-554b-8fd5-5a889c71a066'::uuid, 'Quiz — Un géant commercial, un nain politique ?', 'Histoire-Géographie', 'Tle', 'L’Union européenne : la puissance dans la diversité', '378735ea-1516-5b62-8c6c-655bf1fd3859'::uuid),
