    ('15cec417-a368-50c9-890c-753e2080101e'::uuid, 'Quiz — Une mégalopole, des périphéries, deux rivaux', 'Histoire-Géographie', 'Tle', 'L’Union européenne : entre inégalités territoriales et concurrence mondiale', '7e120658-eed0-5489-a6aa-0d1cde4ee82e'::uuid),
    ('e3729f41-665e-5497-97f7-826a05251270'::uuid, 'Quiz — Relier pour unir', 'Histoire-Géographie', 'Tle', 'Les transports, outils d’ouverture, de cohésion et de compétitivité de l’UE', '67aa8d27-064b-5c9a-a389-a35278b67f93'::uuid),
