    ('92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'Quiz — Ce qui structure la France', 'Histoire-Géographie', 'Tle', 'Les lignes de force du territoire français', '0e4caa1d-31a8-5bbc-bb7a-fdf0b8e16a73'::uuid),
    ('df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'Quiz — Un territoire qu’on redécoupe et qu’on rééquilibre', 'Histoire-Géographie', 'Tle', 'Les recompositions territoriales en France', '0aec4284-76b8-5094-ad22-9ac95c2ada5c'::uuid),
    ('44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Quiz — Ancrée en Europe, présente partout', 'Histoire-Géographie', 'Tle', 'L’intégration de la France en Europe et dans le monde', '64fb9278-f5f7-5028-b81a-a52db5b68fcf'::uuid),
    ('bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quiz — Une région qui gagne des habitants, et des écarts', 'Histoire-Géographie', 'Tle', 'La région Occitanie, entre attractivité, concurrence et inégalité', 'a2a4e23f-7aaa-5d55-bc65-48a81520b352'::uuid)
