-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('c1daf96f-7017-57fa-a127-a2054b184721'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Quelle part du commerce mondial en volume passe par la mer ?', 'mcq', '["Environ 80 %","Environ 30 %","Environ 50 %","Environ 95 %"]'::jsonb, 0, 'La mondialisation des marchandises est d’abord un fait maritime.', 1),
    ('fe62d46c-ce58-5780-a0d5-44bf966494dc'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Qui invente le conteneur en 1956 ?', 'mcq', '["Malcom McLean","Ferdinand de Lesseps","Aristote Onassis","Vincent Bolloré"]'::jsonb, 0, 'La standardisation de la boîte fait s’effondrer le coût du transport.', 2),
    ('c6abe302-8755-5c85-ac55-7a15a7f8191e'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Que mesure l’EVP ?', 'mcq', '["Un volume de conteneurs (équivalent vingt pieds)","Le tonnage d’un navire","La profondeur d’un port","La vitesse d’un porte-conteneurs"]'::jsonb, 0, 'Les plus grands navires dépassent aujourd’hui 20 000 EVP.', 3),
    ('3ce1d8b2-87bf-5bce-b7e7-82addfe70c79'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Quelle part des données mondiales circule par câbles sous-marins ?', 'mcq', '["Environ 99 %","Environ 50 %","Environ 10 %","Environ 75 %"]'::jsonb, 0, 'Le satellite ne joue qu’un rôle marginal : Internet est un réseau sous-marin.', 4),
    ('71ae4df9-d27e-5da1-b88a-b923615b6455'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Quelle largeur la convention de Montego Bay donne-t-elle à une ZEE ?', 'mcq', '["200 milles marins","12 milles marins","50 milles marins","350 milles marins"]'::jsonb, 0, 'Douze milles pour les eaux territoriales, deux cents pour la zone économique exclusive.', 5),
    ('3824d763-409f-5d1e-972b-5bbe0ab9164c'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Le blocage d’un seul point de passage peut perturber le commerce mondial.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’échouage de l’Ever Given dans le canal de Suez en 2021 l’a démontré en quelques jours.', 6),
    ('834aa56d-49bc-5f5f-96b2-e642491581d9'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Comment appelle-t-on la façade maritime européenne allant de Hambourg au Havre ?', 'mcq', '["La Northern Range","La mégalopole bleue","La dorsale atlantique","Le Rhin maritime"]'::jsonb, 0, 'Elle concentre les grands ports d’Europe du Nord-Ouest.', 7),
    ('5f09e7d1-e916-583c-b5a1-ffeece16aaf6'::uuid, 'fa11e5e7-a9b7-5d8f-9697-6c125ea98541'::uuid, 'Les premiers ports mondiaux en tonnage sont européens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le classement est dominé par l’Asie : Shanghai, Singapour, Ningbo, Shenzhen.', 8),
    ('0a1d891a-c3fc-532a-876c-4b9025844e62'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'Que désigne la maritimisation ?', 'mcq', '["Le report vers la mer des enjeux économiques et stratégiques","La montée du niveau des océans","L’augmentation de la pêche industrielle","La construction de ports artificiels"]'::jsonb, 0, 'Les échanges dépendant de la mer, la puissance s’y déplace aussi.', 1),
    ('0369805b-14eb-5864-9db1-92c467cdbd5f'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'Quelle zone concentre les revendications chinoises et la « ligne en neuf traits » ?', 'mcq', '["La mer de Chine méridionale","L’océan Indien","La mer d’Okhotsk","Le golfe du Bengale"]'::jsonb, 0, 'Îlots artificiels militarisés dans les Spratleys et les Paracels.', 2),
    ('224ce690-da18-574c-813f-67c517b67cc4'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'La Chine a respecté la sentence arbitrale de 2016 sur la mer de Chine méridionale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle l’a rejetée et a poursuivi ses aménagements.', 3),
    ('3e461446-5461-5f65-bce7-caf6bca6e63d'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'Où la Chine a-t-elle ouvert sa première base militaire à l’étranger en 2017 ?', 'mcq', '["À Djibouti","Au Sri Lanka","Au Pakistan","En Birmanie"]'::jsonb, 0, 'Position clé à l’entrée de la mer Rouge, sur la route de l’Europe.', 4),
    ('e44473f9-c4b2-5959-9b17-dc2cebce13b4'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'Quelle zone est aujourd’hui la première pour les attaques de pirates ?', 'mcq', '["Le golfe de Guinée","Le golfe d’Aden","Le détroit de Malacca","La mer des Caraïbes"]'::jsonb, 0, 'La piraterie somalienne a reflué, l’Afrique de l’Ouest a pris le relais.', 5),
    ('23584b36-3b18-52a1-9c29-becb6878d22e'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'La fonte de la banquise ouvre de nouvelles routes maritimes en Arctique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La route du Nord raccourcit fortement le trajet Asie-Europe, d’où les revendications.', 6),
    ('ccff0932-594f-5ce9-b851-bbfd3d257d39'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'Pourquoi la possession d’une petite île est-elle stratégique ?', 'mcq', '["Elle ouvre une ZEE de 200 milles marins","Elle permet d’installer un port en eau profonde","Elle donne un siège à l’ONU","Elle échappe aux taxes internationales"]'::jsonb, 0, 'D’où la multiplication des contentieux sur des rochers inhabités.', 7),
    ('e35ae147-cd66-59b5-8879-43479143264c'::uuid, 'a5f4d405-2426-5347-b3f1-6333e15b7276'::uuid, 'La haute mer est aujourd’hui un espace totalement libre et sans revendication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les demandes d’extension du plateau continental territorialisent progressivement l’océan.', 8),
    ('58c50863-c1a0-55e8-a0ab-cc4ee20cf442'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Le détroit de Malacca relie…', 'mcq', '["L’océan Indien à la mer de Chine","La mer Rouge à la Méditerranée","Le Pacifique à l’Atlantique","La mer Noire à la Méditerranée"]'::jsonb, 0, 'C’est la route directe entre le golfe Persique et l’Asie orientale.', 1),
    ('1a69ab9d-f862-512e-8395-c3415b22c0a0'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Quel pays a bâti sa prospérité à la sortie du détroit de Malacca ?', 'mcq', '["Singapour","La Thaïlande","Les Philippines","Le Vietnam"]'::jsonb, 0, 'Transbordement, raffinage et finance en ont fait une plaque tournante mondiale.', 2),
    ('6981890b-7873-57c9-878d-e8103ad069fb'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Qu’appelle-t-on le « dilemme de Malacca » ?', 'mcq', '["La dépendance chinoise à un détroit qu’elle ne contrôle pas","Le choix entre pêche et transport maritime","La pollution du détroit par les pétroliers","Le conflit entre la Malaisie et l’Indonésie"]'::jsonb, 0, 'Environ 80 % des hydrocarbures importés par la Chine y passent.', 3),
    ('63647eac-2631-5944-ba35-25cf611e9809'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Quel détroit ferme le golfe arabo-persique ?', 'mcq', '["Le détroit d’Ormuz","Le détroit de Bab el-Mandeb","Le détroit de Malacca","Le canal de Suez"]'::jsonb, 0, 'Environ 20 millions de barils par jour y transitent.', 4),
    ('7cfde24d-1365-5b98-9189-f59b604ec92a'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'L’Iran a plusieurs fois menacé de fermer le détroit d’Ormuz.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La menace suffit à faire monter les cours mondiaux du pétrole.', 5),
    ('b9bf76ab-2ad8-5214-ae56-da5a2cb53547'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Quelle est la largeur du détroit de Malacca en son point le plus étroit ?', 'mcq', '["Environ 2,7 km","Environ 50 km","Environ 100 km","Environ 900 km"]'::jsonb, 0, '900 km est sa longueur, pas sa largeur.', 6),
    ('6cd06d7f-52db-5a42-9f6a-d57fda314d44'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'La concentration des flux sur quelques passages rend le commerce mondial plus résilient.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : efficacité maximale, vulnérabilité maximale.', 7),
    ('dbca5337-63ee-5f84-9185-ca49f66876ed'::uuid, '7734c7b8-ad05-58b6-9a7a-aeab901df95c'::uuid, 'Quel projet la Chine soutient-elle pour réduire sa dépendance à Malacca ?', 'mcq', '["Des oléoducs vers la Birmanie et le Pakistan","Un pont vers l’Indonésie","Un canal à travers Sumatra","Une flotte de sous-marins civils"]'::jsonb, 0, 'S’y ajoutent les projets de canal de Kra et les routes terrestres de la soie.', 8),
    ('d33273f4-bc81-5333-9d46-3830555896ea'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Quelle part des stocks de poissons est surexploitée ?', 'mcq', '["Environ 35 %","Environ 5 %","Environ 60 %","Environ 90 %"]'::jsonb, 0, 'L’essentiel du reste est exploité à son maximum : les marges sont nulles.', 1),
    ('af0a74e0-4677-5659-bd21-7de3a572f720'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Combien de plastique rejoint l’océan chaque année ?', 'mcq', '["8 à 10 millions de tonnes","100 000 tonnes","500 millions de tonnes","1 million de tonnes"]'::jsonb, 0, 'Il s’accumule dans les gyres puis se fragmente en microplastiques.', 2),
    ('555ed358-7b0f-5ed3-b8a2-dffbc00cf49e'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Pourquoi l’océan s’acidifie-t-il ?', 'mcq', '["Il absorbe une partie du CO₂ émis","Il reçoit des pluies acides","Il se réchauffe","Il reçoit des engrais azotés"]'::jsonb, 0, 'La baisse du pH fragilise coraux et organismes à coquille calcaire.', 3),
    ('fb07aeca-827c-592e-8ea2-cbfb92a7d233'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Que contiennent les nodules polymétalliques convoités au fond des océans ?', 'mcq', '["Nickel, cobalt et manganèse","Pétrole et gaz","Uranium","Sel et magnésium"]'::jsonb, 0, 'Des métaux recherchés pour les batteries — leur exploitation est très contestée.', 4),
    ('41088a6c-bb7d-560d-b085-a5e6d166e7b4'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Quel traité adopté en 2023 permet de créer des aires protégées en haute mer ?', 'mcq', '["Le traité BBNJ","La convention de Montego Bay","Le protocole de Kyoto","L’accord de Nagoya"]'::jsonb, 0, 'Il comble un vide juridique sur 60 % de la surface de l’océan.', 5),
    ('079edf61-6f07-54cb-a4c2-ee52a447735d'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'L’aquaculture fournit aujourd’hui près de la moitié du poisson consommé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec ses propres impacts : intrants, maladies, farines de poisson.', 6),
    ('e045069d-8579-51a5-8746-baa2c5d90041'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Quel objectif international vise la protection des espaces marins ?', 'mcq', '["30 % protégés d’ici 2030","10 % d’ici 2050","50 % d’ici 2040","100 % de la haute mer"]'::jsonb, 0, 'Le taux effectivement protégé et contrôlé reste très en deçà.', 7),
    ('f57b09d6-9558-57b1-96fd-80899e318f3b'::uuid, 'd27efea1-d033-5999-8ab3-c144f1eb8416'::uuid, 'Toutes les aires marines protégées existantes sont réellement surveillées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Beaucoup sont des « parcs de papier » : le classement n’emporte pas le contrôle.', 8),
    ('ea8c2e1d-a2ce-5dc8-89ea-55e78bf968cf'::uuid, '779524fc-cd19-5138-adfa-23124b631580'::uuid, 'Quel rang mondial occupe la ZEE française ?', 'mcq', '["Le 2e","Le 1er","Le 5e","Le 10e"]'::jsonb, 0, 'Environ 10,2 millions de km², derrière les États-Unis.', 1),
