    ('1ef62661-ab83-59de-bc5a-a2c1fb312ba2'::uuid, '5a9f2f20-109b-580b-b3d8-6cfd2ff98e1c'::uuid, 'Quelle agglomération française forme une eurométropole avec Courtrai et Tournai ?', 'mcq', '["Lille","Strasbourg","Metz","Nice"]'::jsonb, 0, 'Un bassin de vie transfrontalier de plus de deux millions d’habitants.', 7),
