    ('456c3fe3-371c-5e52-bda6-cd0493e647df'::uuid, '92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'Quel axe majeur relie Paris à Marseille ?', 'mcq', '["La vallée du Rhône","La vallée de la Seine","Le sillon lorrain","L’arc atlantique"]'::jsonb, 0, 'Autoroute, LGV et fleuve y superposent leurs tracés.', 4),
