    ('74ba95b7-f681-5876-94e4-952006bd86a0'::uuid, '92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'Dans combien d’océans la France d’outre-mer est-elle présente ?', 'mcq', '["Trois","Un","Deux","Quatre"]'::jsonb, 0, 'Atlantique, Indien et Pacifique — d’où l’immensité de la ZEE.', 6),
    ('3f711c13-6ef7-5e2c-b19f-9072bb431110'::uuid, '92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'La croissance économique française est répartie également sur le territoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle se concentre dans une quinzaine de grandes aires urbaines et sur les littoraux.', 7),
    ('46f83561-fe69-5e00-b940-226d9e8ccc9a'::uuid, '92bdc65c-845e-53b4-a54f-72ef3ec86a51'::uuid, 'Quelle façade maritime porte les ports de Rouen et du Havre ?', 'mcq', '["La façade Manche-mer du Nord","La façade atlantique","La façade méditerranéenne","La façade guyanaise"]'::jsonb, 0, 'Elle prolonge l’axe de la vallée de la Seine.', 8),
    ('d89b8417-7395-5c2d-8abe-0c49b2ae16b1'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'De combien de régions métropolitaines la France est-elle passée en 2016 ?', 'mcq', '["De 22 à 13","De 26 à 18","De 13 à 22","De 20 à 15"]'::jsonb, 0, 'Des ensembles plus vastes, censés atteindre une taille européenne.', 1),
    ('48161032-16ce-5ee9-9302-7b388217c652'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'Quelle loi de 2014 crée le statut de métropole ?', 'mcq', '["La loi MAPTAM","La loi NOTRe","La loi SRU","La loi Chevènement"]'::jsonb, 0, 'On compte aujourd’hui 21 métropoles, dont trois à statut particulier.', 2),
