    ('500d612a-0e9b-51d9-b730-fe18a743c7b7'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'Quel programme cible la dévitalisation des centres de villes moyennes ?', 'mcq', '["Action cœur de ville","Grand Paris Express","Territoires zéro chômeur","Plan très haut débit"]'::jsonb, 0, 'Il répond aux commerces vacants et à la vacance des logements de centre-ville.', 4),
    ('3fc1ffb2-e09d-51a1-80ca-50167895bbe4'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'La gentrification des centres métropolitains repousse les ménages modestes vers le périurbain.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’un des mécanismes des fractures territoriales récentes.', 5),
    ('1103435e-d119-54c3-8f13-72099543ec3f'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'Quelle agence pilote depuis 2020 la cohésion des territoires ?', 'mcq', '["L’ANCT","La DATAR","L’ADEME","L’INSEE"]'::jsonb, 0, 'Elle succède notamment à la DATAR dans le rôle d’aménageur.', 6),
