    ('ed962093-ec2d-5fe3-8b43-fbc241c96c73'::uuid, 'df74d159-232c-58f3-a73d-ebde4fc7b4b2'::uuid, 'Quelle évolution a connue la doctrine d’aménagement depuis les années 1960 ?', 'mcq', '["Du rééquilibrage volontariste à la compétitivité des métropoles","De la compétitivité au rééquilibrage","Aucune évolution notable","De l’industrialisation à la ruralisation"]'::jsonb, 0, 'Avec, depuis peu, un retour de la question des territoires en marge.', 8),
    ('36c3301d-590a-5434-bf4a-fe67443a00b1'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Quelle part du commerce extérieur français se fait avec l’Union européenne ?', 'mcq', '["Environ 60 %","Environ 20 %","Environ 90 %","Environ 35 %"]'::jsonb, 0, 'L’Allemagne est de très loin le premier partenaire commercial.', 1),
    ('5fa10c52-9736-53cc-9631-708a80edc6fb'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'De quelle organisation la France est-elle membre fondateur en 1957 ?', 'mcq', '["La CEE","L’OTAN","L’ONU","L’OMC"]'::jsonb, 0, 'Après la CECA en 1951 : l’ancrage européen est ancien et constitutif.', 2),
    ('0c59afc1-4d0e-55ae-850c-233d5cc380b4'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Quel aéroport constitue le principal hub français ?', 'mcq', '["Paris-Charles-de-Gaulle","Nice-Côte d’Azur","Lyon-Saint-Exupéry","Marseille-Provence"]'::jsonb, 0, 'C’est l’une des grandes portes d’entrée du territoire.', 3),
    ('ff2e88c1-2d3f-5ca7-a469-4e09e4fa7e5c'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Où la France dispose-t-elle de forces prépositionnées ?', 'mcq', '["À Djibouti et aux Émirats arabes unis notamment","Uniquement en métropole","Seulement en Afrique de l’Ouest","Uniquement dans l’Union européenne"]'::jsonb, 0, 'S’y ajoutent les Antilles et le Pacifique : une présence sur trois océans.', 4),
    ('1ebf594c-15bc-54c9-ba26-1139eea9684b'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'La France conserve ses parts de marché à l’exportation en Europe.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles reculent, et le déficit commercial est persistant.', 5),
    ('dbea8e4c-63c5-55e4-bafd-40e1fd7a4568'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Quelle politique européenne bénéficie le plus aux agriculteurs français en volume ?', 'mcq', '["La PAC","La politique de cohésion","Le FSE+","Le programme LIFE"]'::jsonb, 0, 'La France en est la première bénéficiaire en montants.', 6),
    ('9aa80cc3-f9a8-5be1-80aa-6c54d28fd780'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'La mondialisation touche uniformément tous les territoires français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quelques métropoles et façades y sont branchées ; d’autres espaces en sont largement déconnectés.', 7),
    ('9cfe395c-183e-5126-b86f-3b163dc07788'::uuid, '44e10d7a-6159-5507-8f84-c46e55d81ef5'::uuid, 'Qu’est-ce qu’une interface dans le vocabulaire géographique ?', 'mcq', '["Une zone de contact entre deux espaces, où passent les flux","Une frontière fermée","Un centre-ville rénové","Une zone industrielle"]'::jsonb, 0, 'Ports, aéroports et gares internationales en sont les exemples types.', 8),
    ('75670199-9a37-50f2-b18e-3b3f6b78004e'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'De quelle fusion l’Occitanie est-elle née en 2016 ?', 'mcq', '["Midi-Pyrénées et Languedoc-Roussillon","Aquitaine et Midi-Pyrénées","Provence et Languedoc","Auvergne et Rhône-Alpes"]'::jsonb, 0, 'Treize départements, des Pyrénées au Massif central.', 1),
    ('3a9dc4f2-12b7-510c-b6ef-043c265e788e'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quel est le principal moteur de la croissance démographique en Occitanie ?', 'mcq', '["Le solde migratoire","Le solde naturel","L’immigration internationale seule","Le retour des expatriés"]'::jsonb, 0, 'Environ +50 000 habitants par an, venus surtout d’autres régions.', 2),
    ('7b9081f7-d8a4-5a09-9118-32ed8d9fedd2'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quelle filière industrielle domine à Toulouse ?', 'mcq', '["L’aéronautique et le spatial","La chimie","Le textile","L’automobile"]'::jsonb, 0, 'Airbus, ses sous-traitants et le CNES en font le premier pôle régional.', 3),
    ('d4fecbb7-23f1-5e94-b338-a46ec94b21e3'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quelle métropole d’Occitanie est spécialisée dans la santé et le numérique ?', 'mcq', '["Montpellier","Nîmes","Perpignan","Albi"]'::jsonb, 0, 'Avec l’une des plus fortes croissances démographiques du pays.', 4),
    ('0d8ecbd4-67ec-54b0-915c-08850f0ac246'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'L’Occitanie a un taux de chômage inférieur à la moyenne nationale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui est durablement supérieur, surtout sur le littoral languedocien.', 5),
    ('9f6863e2-74eb-5c51-805e-098b83099295'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quels départements illustrent les espaces peu denses de la région ?', 'mcq', '["La Lozère et l’Aveyron","L’Hérault et la Haute-Garonne","Le Gard et les Pyrénées-Orientales","Le Tarn et l’Aude uniquement"]'::jsonb, 0, 'Faible densité, vieillissement et éloignement des services y dominent.', 6),
    ('e38b9818-7f19-5826-bec4-0e33a4961953'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Quelle production agricole place l’Occitanie au premier rang français en surface ?', 'mcq', '["La viticulture","La culture du blé","L’élevage bovin","La production de maïs"]'::jsonb, 0, 'Le vignoble languedocien est le plus vaste de France.', 7),
    ('c9e70c57-088f-5ec1-ab49-76f77e2a03d8'::uuid, 'bd540069-f97e-5df0-be39-216b1fc36a15'::uuid, 'Une région attractive est nécessairement une région homogène.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’Occitanie cumule croissance démographique et chômage élevé, métropoles dynamiques et arrière-pays fragiles.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 229 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 229 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
